def digest(value):
    return hashlib.sha256(value.encode()).hexdigest()

def fill(value,context):
    def substitute(match):
        key=match.group(1)
        if key not in context:raise ValueError('Missing complete source identity '+key)
        return str(context[key])
    result=re.sub(r'@@([A-Z0-9_]+)@@',substitute,value)
    if re.search(r'@@[A-Z0-9_]+@@',result):raise ValueError('Unexpanded source identity')
    return result

def function_span(value,name):
    matches=list(re.finditer(r'^def '+re.escape(name)+r'\(',value,re.M))
    if len(matches)!=1:raise ValueError('Expected one full top-level function '+name)
    start=matches[0].start();following=re.search(r'\ndef ',value[start+1:])
    end=len(value) if following is None else start+1+following.start()
    return start,end

def apply(value,operations,context,complete_driver=None):
    result=value
    for operation in operations:
        if operation.get('new_from_complete_driver_parse'):
            left,right=function_span(complete_driver,'parse_args')
            replacement=complete_driver[left:right].replace('    a = p.parse_args()',
                "    p.add_argument('--install-torch', action='store_true')\n"
                "    p.add_argument('--print-command', action='store_true')\n"
                "    a = p.parse_args()")
        else:
            replacement=fill(operation['new'],context)
        if 'function' in operation:
            left,right=function_span(result,operation['function'])
            original=result[left:right]
            if digest(original)!=operation['old_sha256']:
                raise ValueError('A complete original function changed: '+operation['function'])
            result=result[:left]+replacement+result[right:]
        else:
            old=operation['old']
            if result.count(old)!=operation['count']:
                raise ValueError('An exact source replacement has changed cardinality')
            result=result.replace(old,replacement)
    return result

def verify(name,value):
    expected=EXPECTED[name]
    if len(value.encode())>=100000 or len(value.encode())!=expected['bytes'] or digest(value)!=expected['sha256']:
        raise ValueError('A complete rebuilt body differs from its locked identity: '+name)
    tree=ast.parse(value);compile(tree,name,'exec')
    for node in ast.walk(tree):
        if isinstance(node,ast.Call):
            words=[item.arg for item in node.keywords if item.arg is not None]
            if len(words)!=len(set(words)):raise ValueError('Duplicate literal call keyword in '+name)
        elif isinstance(node,ast.Dict):
            words=[item.value for item in node.keys if isinstance(item,ast.Constant) and isinstance(item.value,str)]
            if len(words)!=len(set(words)):raise ValueError('Duplicate literal dictionary key in '+name)
    if any(line.rstrip()!=line for line in value.splitlines()):
        raise ValueError('Trailing source whitespace in '+name)
    return value

